python3 -c '
from pathlib import Path
import re
text = Path("experiment-data/negation-32k.txt").read_text()
data = [line.split("Instance: ",1)[1] for line in text.splitlines() if line.startswith("Date:")]

def analyze(s):
    sl = s.lower().rstrip(".")
    deny = False
    # determine deny
    if sl.startswith("not a single "):
        deny = True
    elif re.match(r"^no [a-z0-9\-]+ (is|may|does|never|commonly)", sl):
        deny = True
    elif "in no context" in sl:
        deny = True
    elif re.search(r"\bin no context\b", sl):
        deny = True
    elif " may not " in sl or sl.startswith("may not"):
        deny = True
    elif " does not " in sl:
        deny = True
    elif " does never " in sl:
        deny = True
    elif " never " in sl or " is never " in sl or " never refers" in sl or " never stands" in sl or sl.endswith(" never") or " never refer" in sl or " never stand" in sl:
        deny = True
    elif " is not " in sl or " is not an " in sl:
        deny = True
    elif "not an appropriate definition" in sl or "not be an appropriate" in sl:
        deny = True
    elif "may not be an appropriate" in sl:
        deny = True
    return deny

deny_c = sum(1 for s in data if analyze(s))
print("deny", deny_c, "affirm", len(data)-deny_c)
# print some deny/affirm samples
for i,s in enumerate(data[:30]):
    print(i, "DENY" if analyze(s) else "AFFIRM", s[:100])
'

